INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13601, 'Psalms 44:18', 'Psalms', 44, 18, '&nbsp;زمونږ زړونه ستا نه نۀ دى اوړېدلى، او زمونږ قدمونه ستا د لارې نه نۀ دى اخوا شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13602, 'Psalms 44:19', 'Psalms', 44, 19, '&nbsp;مونږ دې تباه کړُو او د ګيدړانو ښکار دې کړُو، او په توره تيارۀ کښې دې پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13603, 'Psalms 44:20', 'Psalms', 44, 20, '&nbsp;کۀ مونږ د خپل خُدائ پاک نوم هېر کړے وو، او غېر معبودانو ته مو خپل لاسونه پورته کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13604, 'Psalms 44:21', 'Psalms', 44, 21, '&nbsp;کۀ چرې مونږ داسې کړى وُو نو خُدائ به ترې خبر نۀ وو څۀ؟ ځکه چې هغه د زړونو په رازونو باندې خبر نۀ دے څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13605, 'Psalms 44:22', 'Psalms', 44, 22, '&nbsp;خو مونږ ستا دپاره ټوله ورځ د مرګ سره مخ کيږُو، د خلقو په نظر کښې مونږ د حلالونکو ګډو په شان ګڼلے کيږُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13606, 'Psalms 44:23', 'Psalms', 44, 23, '&nbsp;اے مالِکه خُدايه، راپاڅه ولې تۀ اودۀ کېږې څۀ؟ راپاڅه، او تر ابده پورې مونږ مۀ رد کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13607, 'Psalms 44:24', 'Psalms', 44, 24, '&nbsp;ولې تۀ زمونږ نه خپل مخ پټوې څۀ؟ او زمونږ غم او مصيبتونه ولې هېروې څۀ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13608, 'Psalms 44:25', 'Psalms', 44, 25, '&nbsp;مونږ لاندې خاورو ته راغورزولے شوې يُو، او په زمکه پړمخې پراتۀ يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13609, 'Psalms 44:26', 'Psalms', 44, 26, '&nbsp;پاڅه‎ او زمونږ مدد وکړه، او د خپلې ابدى مينې په وجه دې مونږ ته خلاصون راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13610, 'Psalms 45:1', 'Psalms', 45, 1, '&nbsp;زړۀ کښې مې وګرځېدله څۀ ښکلې شان خبره د بادشاه په حقله زۀ وايم ښۀ غوندې سندره، د ماهر ليکوال په شان قلم دے زما ژبه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13611, 'Psalms 45:2', 'Psalms', 45, 2, '&nbsp;په ټولو سړو کښې د هر چا نه ښائسته يې تۀ ستا د خولې خبرې ښکلې ملغلرې دى، د تل دپاره تۀ خُدائ بختور کړے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13612, 'Psalms 45:3', 'Psalms', 45, 3, '&nbsp;خپله تُوره دې راواخله اے جنګياليه، تۀ ډېر شان او شوکت او دبدبه لرې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13613, 'Psalms 45:4', 'Psalms', 45, 4, '&nbsp;په خپله دبدبه او جلال کښې راشه د کاميابۍ دپاره، چې د حقيقت، عاجزۍ او اِنصاف شې طرفداره ستا ښے لاس دې تا ته يروونکى او عجيبه کارونه کړى در زده', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13614, 'Psalms 45:5', 'Psalms', 45, 5, '&nbsp;ستا تېرۀ غشى دې د دشمنانو زړۀ غوڅ کړى، ستا په پښو کښې دې ټول قومونه راګزار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13615, 'Psalms 45:6', 'Psalms', 45, 6, '&nbsp;اے پاکه خُدايه، ستا تخت، به تر ابده پاتې وى، د اِنصاف امسا به ستا د بادشاهۍ امسا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13616, 'Psalms 45:7', 'Psalms', 45, 7, '&nbsp;تۀ د صداقت سره مينه او د شرارت نه نفرت کوې، نو ځکه خُدائ پاک، ستا خُدائ پاک تۀ د خوشحالۍ په تېلو مسح کړے يې. او تۀ يې په خپلو دوستانو کښې اوچت کړے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13617, 'Psalms 45:8', 'Psalms', 45, 8, '&nbsp;ستا د جامو نه د مصالحو، د پيپل او کيکر عطرو خوشبوئى راځى، ستا په ښکلې محلونو کښې سازونه د رباب تا خوشحالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13618, 'Psalms 45:9', 'Psalms', 45, 9, '&nbsp;ستا عزتمندو ښځو کښې د بادشاهانو لوڼه شاملې دى، د اوفير د زرو ډکه مَلِکه دې ښى لاس ته ولاړه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13619, 'Psalms 45:10', 'Psalms', 45, 10, '&nbsp;اے شهزادګۍ، ما ته غوږ شه، څۀ چې درته زۀ وايم په هغې غور وکړه، د خپل پلار کور او خپل خلق هېر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13620, 'Psalms 45:11', 'Psalms', 45, 11, '&nbsp;ستا ډول او سنګار به بادشاه خپل طرف ته راکاږى، ځکه چې هغه ستاسو مالِک دے د هغۀ تابعدارې اوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13621, 'Psalms 45:12', 'Psalms', 45, 12, '&nbsp;تا له د ډالو سره د صور خلق به راشى، دولتمند خلق به ستا مهربانى غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13622, 'Psalms 45:13', 'Psalms', 45, 13, '&nbsp;شهزادګۍ به په محل کښې ښکلې ښکارى، د سرو زرو تارونو نه يې جامې دى جوړې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13623, 'Psalms 45:14', 'Psalms', 45, 14, '&nbsp;د ګُلکارۍ په جامو کښې يې بادشاه له راوستله، پېغلې ملګرې هم ورسره راروانې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13624, 'Psalms 45:15', 'Psalms', 45, 15, '&nbsp;خاندى خوشحاليږى راروانې دى، او د بادشاه محل ته رادننه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13625, 'Psalms 45:16', 'Psalms', 45, 16, '&nbsp;ستا زامن به د خپل پلار نيکۀ په شان بادشاهان جوړ شى، تۀ به هغوئ په ډېرو مُلکونو حکمرانان جوړ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13626, 'Psalms 45:17', 'Psalms', 45, 17, '&nbsp;نسل در نسل به زۀ ستا نوم د عزت قابل کړم، نو قومونه به تر ابده پورې ستا ثناء خوان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13627, 'Psalms 46:1', 'Psalms', 46, 1, '&nbsp;خُدائ پاک زمونږ پناه ګاه او قوت دے، په وخت د مصيبت کښې حاضر او تل مددګار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13628, 'Psalms 46:2', 'Psalms', 46, 2, '&nbsp;نو مونږ به نۀ يريږو کۀ په زمکه زلزله راشى، او کۀ غرونه د سمندر په مينځ کښې راګزار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13629, 'Psalms 46:3', 'Psalms', 46, 3, '&nbsp;او يا د سمندر اوبۀ غرار او ځګونه وکړى، او غرونه د اوبو د زور په وجه وخوځولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13630, 'Psalms 46:4', 'Psalms', 46, 4, '&nbsp;يو بل درياب دے چې نِهرونه يې د خُدائ پاک ښار خوشحالوى، او د خُدائ تعالىٰ مقدس کور خوشحالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13631, 'Psalms 46:5', 'Psalms', 46, 5, '&nbsp;او خُدائ پاک د هغه ښار په مينځ کښې اوسيږى نو هغه به نۀ تباه کيږى، او د سحر وختى نه د هغه ښار ساتنه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13632, 'Psalms 46:6', 'Psalms', 46, 6, '&nbsp;قومونه وارخطا دى، بادشاهتونه به نسکور شى. کله چې خُدائ پاک آواز وکړى نو دا زمکه به ويلى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13633, 'Psalms 46:7', 'Psalms', 46, 7, '&nbsp;ربُ الافواج خُدائ زمونږ مل دے، د يعقوب خُدائ پاک زمونږ پناه ګاه دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13634, 'Psalms 46:8', 'Psalms', 46, 8, '&nbsp;راشئ او د مالِک خُدائ کارونه وګورئ، هغه تباهى چې کومه هغۀ په دُنيا باندې راوستلې ده وګورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13635, 'Psalms 46:9', 'Psalms', 46, 9, '&nbsp;هغه په ټوله دُنيا کښې جنګونه ختموى، ليندې او نېزې ماتوى او ډالونه سوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13636, 'Psalms 46:10', 'Psalms', 46, 10, '&nbsp;”په آرام شئ او په دې پوهه شئ زۀ خُدائ پاک يم، زۀ به په ټولو قومونو کښې اعلىٰ يم، زۀ به په ټوله دُنيا کښې اوچت يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13637, 'Psalms 46:11', 'Psalms', 46, 11, '&nbsp;ربُ الافواج خُدائ زمونږ مل دے، د يعقوب خُدائ پاک زمونږ پناه ګاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13638, 'Psalms 47:1', 'Psalms', 47, 1, '&nbsp;اے ټولو خلقو لاسونه ووهئ، او د خوشحالۍ سرود په اوچت آواز سره ووايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13639, 'Psalms 47:2', 'Psalms', 47, 2, '&nbsp;مالِک خُدائ تعالىٰ څومره د رُعب داب مالِک دے، هغه په ټولې دُنيا لوئ بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13640, 'Psalms 47:3', 'Psalms', 47, 3, '&nbsp;هغۀ ټول قومونه زمونږ تابع کړل، او مُلکونه يې زمونږ د پښو لاندې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13641, 'Psalms 47:4', 'Psalms', 47, 4, '&nbsp;مونږ له يې په ميراث کښې زمکه راکړله، په کومه چې يعقوب فخر کولو او د هغه چا سره چې خُدائ مينه کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13642, 'Psalms 47:5', 'Psalms', 47, 5, '&nbsp;خُدائ پاک د خلقو په چغو سورو کښې تخت ته خېژى، چې مالِک خُدائ بره تخت ته ځى نو د بيګلو آوازونه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13643, 'Psalms 47:6', 'Psalms', 47, 6, '&nbsp;د خُدائ پاک ثناء صِفت کوئ ثنا يې ووايئ، زمونږ بادشاه ته سندرې او ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13644, 'Psalms 47:7', 'Psalms', 47, 7, '&nbsp;ځکه خُدائ پاک په ټوله زمکه بادشاه دے، هغۀ ته د ثناء حمد، زبور ووايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13645, 'Psalms 47:8', 'Psalms', 47, 8, '&nbsp;خُدائ په خپل مقدس تخت باندې ناست دے، او په ټولو قومونو بادشاهى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13646, 'Psalms 47:9', 'Psalms', 47, 9, '&nbsp;د دُنيا حکمرانان رايوځائ شوى دى، د اِبراهيم د خُدائ خلق ورسره دى، د دُنيا ټول بادشاهان د خُدائ پاک دى، نو ځکه د هغۀ په هر ځائ کښې ډېر عزت کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13647, 'Psalms 48:1', 'Psalms', 48, 1, '&nbsp;مالِک خُدائ لوئ دے، او د ثناء صِفت لائق دے، زمونږ د خُدائ په ښار، يعنې مقدس غر کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13648, 'Psalms 48:2', 'Psalms', 48, 2, '&nbsp;د هغۀ ښار په خپل اوچتوالى کښې ښکلے دے، او ټولې دُنيا ته خوشحالى ورکوى. د صيون غر او مقدس غر چې د لوئ بادشاه ښار دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13649, 'Psalms 48:3', 'Psalms', 48, 3, '&nbsp;خُدائ په خپله د دې ښار په برجونو کښې موجود دے، او خپل ځان يې د ښار محافظ ښودلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13650, 'Psalms 48:4', 'Psalms', 48, 4, '&nbsp;وګوره چې د دُنيا بادشاهانو لښکرې رايوځائ کړې او متحد شول، او د ښار په خلاف د جنګ په خيال راوړاندې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13651, 'Psalms 48:5', 'Psalms', 48, 5, '&nbsp;هغوئ چې هغه ښار وليدو نو حق حېران شول، ټول د يرې نه په تېښته وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13652, 'Psalms 48:6', 'Psalms', 48, 6, '&nbsp;هغوئ هلته د يرې نه شول په لړزان، څنګه چې په تکليف پېدا کيږى ماشومان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13653, 'Psalms 48:7', 'Psalms', 48, 7, '&nbsp;لکه د ترسيس د بحرى بيړو په شان تا هغوئ تباه کړل، د زورَور مشرقى بادونو په زور دې تس نس کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13654, 'Psalms 48:8', 'Psalms', 48, 8, '&nbsp;لکه څنګه چې مونږ اورېدلى نو اوس مو په خپلو سترګو وليدل، زمونږ د خُدائ په ښار يعنې د ربُ الافواج په ښار کښې، خُدائ به تل دا ښار آبادولو او د هغې حفاظت به يې کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13655, 'Psalms 48:9', 'Psalms', 48, 9, '&nbsp;اے پاکه خُدايه، مونږ ستا په عبادتګاه کښې يُو، او ستا په نۀ ختمېدونکې مينې باندې فکر کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13656, 'Psalms 48:10', 'Psalms', 48, 10, '&nbsp;اے خُدايه، لکه څنګه چې دې نوم په ټوله دُنيا خور ‎دے، دغه شان ستا ثناء صِفت په ټوله دُنيا خور دے، ستا ښے لاس د صداقت نه ډک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13657, 'Psalms 48:11', 'Psalms', 48, 11, '&nbsp;د صيون د غرۀ خلق دې خوشحالى وکړى، او د يهوداه ټول ښارونه دې خوشحالى وکړى دا ټول دې ستا د عدالت په وجه خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13658, 'Psalms 48:12', 'Psalms', 48, 12, '&nbsp;صيون ته لاړ شئ او ګېرچاپېره ترې نه وګرځئ، او برجونه يې وشمېرئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13659, 'Psalms 48:13', 'Psalms', 48, 13, '&nbsp;دېوالونو ته يې وګورئ او په محلونو يې نظر واچوئ، ترڅو تاسو د هغې نه خپل آئنده نسلونه خبر کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13660, 'Psalms 48:14', 'Psalms', 48, 14, '&nbsp;ځکه چې هم دا خُدائ د تل دپاره زمونږ خُدائ پاک دے، هغه تر آخر وخته زمونږ رهنما دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13661, 'Psalms 49:1', 'Psalms', 49, 1, '&nbsp;اے قومونو تاسو ټول دا واورئ، څوک چې په دُنيا کښې اوسېږئ ما ته غوږ ونيسئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13662, 'Psalms 49:2', 'Psalms', 49, 2, '&nbsp;خاصو او عامو، مالدارو او غريبانو واورئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13663, 'Psalms 49:3', 'Psalms', 49, 3, '&nbsp;زما ژبه په حِکمت سره خبرې بيانوى، او د زړۀ بيان مې خلقو ته پوهه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13664, 'Psalms 49:4', 'Psalms', 49, 4, '&nbsp;زۀ به متلونو ته خپل غوږ ونيسمه، د رباب په ساز کښې به زۀ د راز وينا وکړمه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13665, 'Psalms 49:5', 'Psalms', 49, 5, '&nbsp;نو زۀ به ولې يرېږمه کۀ سخته په ما راشى، کله چې د دوکه مارو په شرارتونو کښې راګېر شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13666, 'Psalms 49:6', 'Psalms', 49, 6, '&nbsp;دوئ چې په خپل مال دولت باندې يقين لرى، او په خپل ډېر مال دولت فخر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13667, 'Psalms 49:7', 'Psalms', 49, 7, '&nbsp;هيڅوک د چا د ژوند قيمت ورکولے نۀ شى، او نۀ خُدائ پاک له د هغۀ د سر کفاره ورکولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13668, 'Psalms 49:8', 'Psalms', 49, 8, '&nbsp;د ژوندون قيمت بې‌بها دے، د ژوندون دپاره هيڅ قيمت پوره نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13669, 'Psalms 49:9', 'Psalms', 49, 9, '&nbsp;چې هغه دې تر ابده ژوندے پاتې شى، او هيڅکله دې قبر ته لاړ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13670, 'Psalms 49:10', 'Psalms', 49, 10, '&nbsp;نو ټول خلق به ووينى چې پوهان هم مړۀ کيږى، جاهلان او بې‌وقوفان به يو ځائ هلاک شى. او د ټولو نه به مال دولت نورو ته پاتې شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13671, 'Psalms 49:11', 'Psalms', 49, 11, '&nbsp;قبر د هغوئ ابدى کور دے، چرته چې به هغوئ د تل دپاره وى، کۀ څۀ هم چې هغوئ جائيدادونه په خپل نوم خېژولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13672, 'Psalms 49:12', 'Psalms', 49, 12, '&nbsp;خو انسانان د خپل دولت په وجه ژوندى پاتې کېدے نۀ شى، او هغوئ به لکه د ځناور په شان مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13673, 'Psalms 49:13', 'Psalms', 49, 13, '&nbsp;دا د هغوئ نصيب دے څوک چې په خپل ځان توکل کوى، او څوک چې د دوئ په لاره روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13674, 'Psalms 49:14', 'Psalms', 49, 14, '&nbsp;د ګډو د رمې په شان هسې به د مرګ کندې ته ګزار شى، چرته چې مرګ به د دوئ شپون وى. په سحر کښې به نېکان په دوئ حکومت کوى، د دوئ بدن به په قبر کښې ختم شى، او قبر به د دوئ کور شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13675, 'Psalms 49:15', 'Psalms', 49, 15, '&nbsp;خو خُدائ پاک به ما له د قبر نه خلاصون راکړى، ځکه چې هغه به ضرور ما خپل ځان ته راکاږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13676, 'Psalms 49:16', 'Psalms', 49, 16, '&nbsp;هيڅکله مۀ خفه کېږه کۀ يو سړے مالداره کيږى، او د چا د کور شان او شوکت چې زياتيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13677, 'Psalms 49:17', 'Psalms', 49, 17, '&nbsp;ځکه چې کله هغه مړ شى د ځان سره به هيڅ څيز نۀ وړى، د هغۀ شان او شوکت به قبر ته د هغۀ سره نۀ ځى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13678, 'Psalms 49:18', 'Psalms', 49, 18, '&nbsp;کله چې هغه ژوندے وو خپل ځان يې بختور ګڼلو، خلقو يې صِفتونه کول کله چې مالداره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13679, 'Psalms 49:19', 'Psalms', 49, 19, '&nbsp;خو د خپل پلار او نيکۀ په شان دوئ به آخر مړۀ شى، نو کله به هم دوئ د ژوندون رڼا ونۀ وينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13680, 'Psalms 49:20', 'Psalms', 49, 20, '&nbsp;هغه څوک چې ډېر مال او دولت لرى خو دے نۀ پوهيږى چې دوئ به د ځناورو په شان ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13681, 'Psalms 50:1', 'Psalms', 50, 1, '&nbsp;قادر مطلق خُدائ، مالِک خُدائ د زمکې خلقو ته حُکم وکړو، او د مشرق نه تر مغرب پورې د زمکې خلق يې راوغوښتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13682, 'Psalms 50:2', 'Psalms', 50, 2, '&nbsp;د صيون نه چې په ښائست باندې پوره دے نو خُدائ پاک د هغه ځائ نه ځلېدلے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13683, 'Psalms 50:3', 'Psalms', 50, 3, '&nbsp;زمونږ خُدائ به راشى او خاموشه به نۀ وى سوزېدونکے اور به ترې نه مخکښې او سخت طوفان به ترې چاپېره وى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13684, 'Psalms 50:4', 'Psalms', 50, 4, '&nbsp;هغه به زمکه او پاس آسمانونه ګواهۍ دپاره راوغواړى چې د خپل قوم عدالت وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13685, 'Psalms 50:5', 'Psalms', 50, 5, '&nbsp;”زما ټول نېکان ما ته راغونډ کړئ چا چې ما سره د قربانۍ په ذريعه لوظ کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13686, 'Psalms 50:6', 'Psalms', 50, 6, '&nbsp;آسمانونه د هغۀ د صداقت اعلان کوى ځکه چې په خپله خُدائ قاضى فېصله کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13687, 'Psalms 50:7', 'Psalms', 50, 7, '&nbsp;”اے زما خلقو ما ته غوږ شئ زۀ به تاسو ته خبرې وکړم اے بنى اِسرائيلو زۀ ستاسو خلاف دا ګواهى کوم. چې هم زۀ خُدائ يم او ستاسو خُدائ پاک يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13688, 'Psalms 50:8', 'Psalms', 50, 8, '&nbsp;ستاسو د قربانيانو په وجه زۀ تاسو نۀ رټم، او ستاسو مسلسل سوزېدونکې قربانيانې زما په وړاندې دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13689, 'Psalms 50:9', 'Psalms', 50, 9, '&nbsp;ستاسو د غوجل غوَيى ته زما ضرورت نشته او نۀ مې حاجت شته ستاسو د شپول يو چېلى ته', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13690, 'Psalms 50:10', 'Psalms', 50, 10, '&nbsp;ولې چې د ځنګلونو ټول او هر يو ځناور زما دى، او په زرګونو غرونو کښې د څاروو رمې زما دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13691, 'Psalms 50:11', 'Psalms', 50, 11, '&nbsp;زۀ د غرونو هر يو مارغۀ نه خبر يم، او د هوارو ټول مخلوق زما دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13692, 'Psalms 50:12', 'Psalms', 50, 12, '&nbsp;کۀ چرې زۀ اوږے شوے وم خو بيا هم به مې وئيلى نۀ وُو تا ته، ځکه چې دُنيا او څۀ چې په کښې دى هغه ټول زما دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13693, 'Psalms 50:13', 'Psalms', 50, 13, '&nbsp;ولې زۀ څۀ د غوَيانو غوښې خورم؟ او يا زۀ د چېلو وينې څښم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13694, 'Psalms 50:14', 'Psalms', 50, 14, '&nbsp;ستاسو قربانۍ خُدائ ته شُکر ګزارى کول دى، او دا ستاسو د خُدائ تعالىٰ سره کړې وعدې او نذرانې پوره کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13695, 'Psalms 50:15', 'Psalms', 50, 15, '&nbsp;په وخت د مصيبت کښې ما ته آواز راکړئ، زۀ به تاسو د مصيبت نه بچ کړمه او تاسو به زما عزت وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13696, 'Psalms 50:16', 'Psalms', 50, 16, '&nbsp;خو بدعمله ته خُدائ پاک وفرمائيل، ”تاسو ولې زما قانون بيانوئ، او زما د لوظ خبرې په خپله ژبه کوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13697, 'Psalms 50:17', 'Psalms', 50, 17, '&nbsp;تاسو د اصلاح نه نفرت کوئ او تاسو زما حُکمونه شاته غورزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13698, 'Psalms 50:18', 'Psalms', 50, 18, '&nbsp;کله چې غل ووينئ نو تاسو ورسره مل شئ، تاسو ملګرتيا د زناکارو کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13699, 'Psalms 50:19', 'Psalms', 50, 19, '&nbsp;هر وخت مو ژبه د بدۍ نه ډکه وى، تۀ په خپله ژبه د دروغو خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13700, 'Psalms 50:20', 'Psalms', 50, 20, '&nbsp;هر وخت تاسو د خپل ورور خلاف خبرې کوئ، د خپلې مور د بچى تاسو هر ځائ کښې غېبت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');